// Determine which email to send based on days since creation
const items = $input.all();
const results = [];

items.forEach(item => {
  const lead = item.json;
  const createdDate = new Date(lead['Created At']);
  const now = new Date();
  const daysSinceCreated = Math.floor((now - createdDate) / (1000 * 60 * 60 * 24));

  let emailTemplate = null;
  let subject = '';

  // Determine which email in sequence
  if (daysSinceCreated === 2) {
    emailTemplate = 'day2';
    subject = 'The #1 Mistake People Make';
  } else if (daysSinceCreated === 4) {
    emailTemplate = 'day4';
    subject = 'How [Solution] Can Help You';
  } else if (daysSinceCreated === 6) {
    emailTemplate = 'day6';
    subject = 'Real Results: [Customer] Story';
  } else if (daysSinceCreated === 8) {
    emailTemplate = 'day8';
    subject = '20% Off - Limited Time';
  } else if (daysSinceCreated === 10) {
    emailTemplate = 'day10';
    subject = 'Last Chance: Your Exclusive Offer';
  }

  if (emailTemplate) {
    results.push({
      json: {
        ...lead,
        emailTemplate,
        subject,
        daysSinceCreated
      }
    });
  }
});

return results;
